   # --- Abstract and semi-abstract methods -------------------------------

   @abc.abstractmethod
   def close(self):
       """Close the file.

       After the file is closed, any other operation on it will
       raise a ValueError.
       """
       # If a subclass defines __slots__, the closed attribute may not be
       # available.
       if not self.closed:
           self._closed = True

   @property
   @abc.abstractmethod
   def closed(self):
       """A boolean saying whether the file is closed."""
       raise NotImplementedError

   def flush(self):
       """Flush write buffers, if applicable.

       This method has no effect on unbuffered and raw streams.
       """

   @abc.abstractmethod
